#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define MAX_STACK 64

int main(int argc, char *argv[])
{
    long stack[MAX_STACK];
    int top = 0;
    if (argc < 2) {
        puts("ERROR");
        return 0;
    }
    for (int i = 1; i < argc; ++i) {
        char *tok = argv[i];
        if (strlen(tok) == 1) {
            char op = tok[0];
            if (op == '+' || op == '-' || op == '*' || op == '/') {
                if (top < 2) { puts("ERROR"); return 0; }
                long b = stack[--top];
                long a = stack[--top];
                long res;
                if (op == '+') res = a + b;
                else if (op == '-') res = a - b;
                else if (op == '*') res = a * b;
                else {
                    if (b == 0) { puts("ERROR"); return 0; }
                    res = a / b;
                }
                if (top >= MAX_STACK) { puts("ERROR"); return 0; }
                stack[top++] = res;
                continue;
            }
        }
        char *endptr;
        errno = 0;
        long val = strtol(tok, &endptr, 10);
        if (endptr == tok || *endptr != '\0' || errno != 0) { puts("ERROR"); return 0; }
        if (top >= MAX_STACK) { puts("ERROR"); return 0; }
        stack[top++] = val;
    }
    if (top == 1) {
        printf("%ld\n", stack[0]);
    } else {
        puts("ERROR");
    }
    return 0;
}
